CREATE OR REPLACE FUNCTION public.icash_capture_seller_viewing(p_account uuid, p_deal uuid, p_thread uuid, p_source text, p_id uuid, p_turns jsonb, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;turn jsonb;previous text:='';answer text;quote text:='';slots jsonb:='[]';slot jsonb;slot_state text:='available';candidate boolean;correction boolean;has_schedule boolean;
begin
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account and deal_id=p_deal and party='seller' and retired_at is null;if not found then return;end if;
 select * into d from public.icash_deal_files where id=p_deal and account_id=p_account and stage in ('under_contract','buyer_selected','title_open','closing');
 if not found or coalesce(d.terms->>'practice','false')='true' or not exists(select 1 from public.icash_signing_envelopes where account_id=p_account and deal_id=p_deal and kind='purchase' and state='completed' and not test_mode) then return;end if;
 if jsonb_typeof(p_turns) is distinct from 'array' or jsonb_array_length(p_turns)>80 or p_at>now() or p_at<now()-interval '30 days' then return;end if;
 has_schedule:=exists(select 1 from public.icash_seller_viewing_availability where account_id=p_account and deal_id=p_deal and stated_at<=p_at);
 for turn in select value from jsonb_array_elements(p_turns) loop
  answer:=btrim(turn->>'message');
  if turn->>'role'='agent' then previous:=answer;continue;end if;
  if turn->>'role'<>'user' or length(answer) not between 1 and 1500 then continue;end if;
  correction:=(quote<>'' or has_schedule) and answer ~* '^((actually[, ]+)?make it|change (it|that) to|instead)\M';
  candidate:=correction or (previous ~* '\m(viewing|viewings|showing|showings|visit|tour|access)\M' and previous ~* '\m(day|days|date|dates|time|times|when|available|availability|works|work|window|windows)\M')
   or (answer ~* '\m(viewing|viewings|showing|showings|visit|tour)\M' and answer ~* '\m(available|cancel|cannot|can''t|works|work|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\M');
  if not candidate or answer ~* '^(yes|yeah|yep|correct|that works|those work|ok|okay|thanks|thank you)[.! ]*$' then continue;end if;
  if answer !~ '[[:alnum:]]' then continue;end if;
  quote:=left(case when quote='' then answer else quote||E'\n'||answer end,4000);
  if correction then
   -- Hold a changed time until the complete replacement is clarified. Never
   -- keep advertising the old slot merely because the word viewing was omitted.
   slots:='[]';slot_state:='needs_review';
  elsif answer ~* '\m(cancel|unavailable|cannot|can''t|not|don''t|do not|no longer|never)\M' then
   slots:='[]';slot_state:=case when answer ~* '\m(cancel|no longer|unavailable)\M' then 'withdrawn' else 'needs_review' end;
  else
   slot:=public.icash_parse_viewing_slot(answer,p_at);
   if slot is null then slot_state:='needs_review';slots:='[]';
   else
    if slot_state<>'available' then slots:='[]';end if;
    slot_state:='available';
    if jsonb_array_length(slots)<8 then slots:=slots||jsonb_build_array(slot);end if;
   end if;
  end if;
 end loop;
 if quote='' then return;end if;
 if slot_state<>'available' then slots:='[]';end if;
 insert into public.icash_seller_viewing_availability(account_id,deal_id,screening_id,thread_id,source,source_id,quote,slots,state,timezone,stated_at)
 values(p_account,p_deal,d.screening_id,t.id,p_source,p_id,quote,slots,slot_state,t.timezone,p_at) on conflict do nothing;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_seller_agreement_before_offer(p_hash text, p_conversation text, p_confirmation jsonb, p_expected_terms jsonb, p_terms jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;d public.icash_deal_files;prior icash_seller_agreement_private.confirmations;e public.icash_signing_envelopes;new_id uuid;
begin
 c:=public.icash_seller_agreement_call_context(p_hash,p_conversation);if c is null then return null;end if;
 select * into d from public.icash_deal_files where id=(c->>'dealId')::uuid and account_id=(c->>'accountId')::uuid for update;
 select * into prior from icash_seller_agreement_private.confirmations where call_key=c->>'callKey';
 if found then
  if prior.confirmation is distinct from p_confirmation then return null;end if;
  return jsonb_build_object('id',prior.id,'claimed',false,'envelopeId',prior.envelope_id);
 end if;
 if d.stage<>'draft' or d.terms is distinct from p_expected_terms or jsonb_typeof(p_confirmation)<>'object' or jsonb_typeof(p_terms)<>'object'
  or p_confirmation->'soleOwner' is distinct from 'true'::jsonb or p_confirmation->'allDecisionMakersAgree' is distinct from 'true'::jsonb
  or p_confirmation->'priceAndDateConfirmed' is distinct from 'true'::jsonb or p_confirmation->'termsConfirmed' is distinct from 'true'::jsonb
  or p_confirmation->'sendTextRequested' is distinct from 'true'::jsonb or p_confirmation->'materialFactsChanged' is distinct from 'false'::jsonb
  or coalesce(p_confirmation->>'inspectionAccess','') not in ('yes','no')
  or p_terms->'priceCents' is distinct from p_confirmation->'agreedPriceCents' or p_terms->>'seller' is distinct from p_confirmation->>'sellerLegalName'
  or p_terms->>'closingDate' is distinct from p_confirmation->>'closingDate'
  or row(p_terms->'address',p_terms->'buyer',p_terms->'state') is distinct from row(d.terms->'address',d.terms->'buyer',d.terms->'state') then return null;end if;
 select * into e from public.icash_signing_envelopes where account_id=d.account_id and deal_id=d.id and kind='purchase' and not test_mode;
 if found then
  if e.state<>'awaiting_counterparty' or e.terms is distinct from p_terms or jsonb_array_length(e.recipients)<>2 or e.recipients->0->>'phone' is distinct from c->>'phone' then return null;end if;
 else
  update public.icash_deal_files set terms=p_terms,updated_at=now() where id=d.id;
 end if;
 insert into icash_seller_agreement_private.confirmations(call_key,account_id,deal_id,confirmation,terms,envelope_id,state)
 values(c->>'callKey',d.account_id,d.id,p_confirmation,p_terms,e.id,case when e.id is null then 'preparing' else 'ready' end) returning id into new_id;
 return jsonb_build_object('id',new_id,'claimed',true,'envelopeId',e.id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_open_handoff(p_call uuid, p_reason text, p_summary text, p_next text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_live_conversations; prop text; result uuid;
begin
 select * into strict c from public.icash_live_conversations where id=p_call for update;
 if length(p_reason) not between 1 and 1000 or length(p_summary)>6000 or length(p_next) not between 1 and 1000 then raise exception 'Invalid handoff';end if;
 select snapshot->>'propertyId' into strict prop from public.icash_screening_jobs where id=c.screening_id and account_id=c.account_id;
 insert into public.icash_property_controls(account_id,property_id,manual) values(c.account_id,prop,true)
 on conflict(account_id,property_id) do update set manual=true,updated_at=now();
 insert into public.icash_handoffs(conversation_id,account_id,screening_id,party,reason,summary,next_action)
 values(c.id,c.account_id,c.screening_id,c.party,p_reason,p_summary,p_next)
 on conflict(conversation_id) do update set summary=excluded.summary
 returning id into result;
 update public.icash_live_callbacks set state='held_for_human' where account_id=c.account_id and screening_id=c.screening_id and state='pending_dispatch_review';
 return result;
end $function$
